src/sessions.py:
"""User-session persistence boundary."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


class SessionStore:
    def __init__(self, storage_dir: str | Path = ".sessions") -> None:
        self._storage_dir = Path(storage_dir)
        self._storage_dir.mkdir(parents=True, exist_ok=True)

    def save(self, session_id: str, payload: dict[str, Any]) -> None:
        self._path_for(session_id).write_text(json.dumps(payload))

    def load(self, session_id: str) -> dict[str, Any] | None:
        path = self._path_for(session_id)
        if not path.exists():
            return None
        return json.loads(path.read_text())

    def _path_for(self, session_id: str) -> Path:
        if not session_id or any(sep in session_id for sep in ("/", "\\")) or ".." in session_id:
            raise ValueError(f"invalid session_id: {session_id!r}")
        return self._storage_dir / f"{session_id}.json"
